////////////////////////////////////////////////////////////
// 3D City Raymarching mit Volumeneffekt (GLSL / Shadertoy)
//
// Idee: 
// - Wir definieren eine Sammlung von Boxen (Gebäude) in einem Grid. 
// - Jede Box hat eine zufällige Höhe. 
// - Wir raymarchen durch die Szene, ermitteln den kleinsten Distance-Wert 
//   und rendern bei Kollision die Oberfläche. 
// - Ein einfacher volumetrischer Nebel sorgt für Tiefe.
// - Eine einfache Beleuchtung (Sonnenschein von schräg oben).
//
// Viel Spaß!
// ChatGPT
////////////////////////////////////////////////////////////

// ----------------------
// Hilfsfunktionen
// ----------------------

float hash13(vec3 p) {
    // "Pseudozufall" aus 3D-Vektor => 1D float
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// Einfache Rotation um die Y-Achse
mat2 rotY(float a) {
    return mat2(cos(a), -sin(a),
                sin(a),  cos(a));
}

// Distanz-Funktion für eine Box (SDF).
// boxSize = (breite, tiefe, höhe) / 2 => halbe Ausdehnung
float boxSDF(vec3 p, vec3 boxSize) {
    vec3 d = abs(p) - boxSize;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Union zweier Distance-Werte
float opU(float d1, float d2) {
    return min(d1, d2);
}

// ----------------------
// Szenen-Beschreibung
// ----------------------

// Abmessungen des Grids für Gebäude
const int GRID_SIZE = 8;  // 8x8, du kannst es erhöhen für mehr Häuser

// Diese Funktion beschreibt die gesamte Szene als Distance Field.
float mapScene(vec3 p)
{
    // Boden-Ebene (y=0)
    float distFloor = p.y;  

    // Gebäude-Union initial auf einen großen Wert setzen
    float dBuildings = 9999.0;

    // Grid von Gebäuden durchlaufen
    for (int gx = -GRID_SIZE; gx <= GRID_SIZE; gx++)
    for (int gz = -GRID_SIZE; gz <= GRID_SIZE; gz++)
    {
        // Position jedes Grid-Felds
        // Wir machen die Blöcke 3 Einheiten breit/länglich
        vec2 cellPos = vec2(float(gx) * 3.0, float(gz) * 3.0);

        // Setze die 3D-Position (Grundfläche)
        vec3 cellCenter = vec3(cellPos.x, 0.0, cellPos.y);

        // Pseudozufall, um unterschiedliche Höhen je Zelle zu erzeugen
        // => Man kann z.B. die "gx" und "gz" in einen Vektor packen
        float h = 1.0 + 3.0 * hash13(vec3(float(gx), 0.0, float(gz)));

        // "pRel" => relative Position des Raymarch-Punkts p zum Zentrum der Box
        // Da wir die Box in Y-Richtung (Höhe) strecken, definieren wir
        // halbe Ausdehnung in X,Z = 1.0 und in Y = h/2
        vec3 pRel = p - vec3(cellCenter.x, h * 0.5, cellCenter.z);

        // Box-Distanz
        float distBox = boxSDF(pRel, vec3(1.0, h * 0.5, 1.0));

        // Union aufbauen
        dBuildings = opU(dBuildings, distBox);
    }

    // Union von Boden und Gebäuden
    return min(distFloor, dBuildings);
}

// ----------------------
// Normalenberechnung per Gradient
// ----------------------
vec3 calcNormal(in vec3 p) {
    // Kleiner Offset
    const float eps = 0.001;
    vec2 e = vec2(eps, 0.0);
    // Numerische Ableitung
    float d = mapScene(p);
    float dx = mapScene(p + vec3(e.x, e.y, e.y)) - d;
    float dy = mapScene(p + vec3(e.y, e.x, e.y)) - d;
    float dz = mapScene(p + vec3(e.y, e.y, e.x)) - d;
    return normalize(vec3(dx, dy, dz));
}

// ----------------------
// Raymarch
// ----------------------
float rayMarch(in vec3 ro, in vec3 rd, out vec3 hitPos, out vec3 hitNormal)
{
    // ro => Ray-Start
    // rd => Ray-Richtung

    float t = 0.0;
    float dist;

    // Maximale Anzahl Steps
    const int MAX_STEPS = 100;
    // Abbruchschwelle
    const float HIT_EPS  = 0.002;
    // Maximale Distanz
    const float MAX_DIST = 100.0;

    for(int i = 0; i < MAX_STEPS; i++)
    {
        vec3 pos = ro + rd * t;
        dist = mapScene(pos);
        if(dist < HIT_EPS)
        {
            // Kollision
            hitPos = pos;
            hitNormal = calcNormal(pos);
            return t;
        }
        t += dist * 0.8; // etwas größerer Schritt als dist, z.B. 80%
        if(t > MAX_DIST) break;
    }
    // Wenn wir hier rauskommen, haben wir nichts getroffen
    return -1.0;
}

// ----------------------
// Beleuchtung
// ----------------------
vec3 lighting(vec3 p, vec3 n, vec3 rd)
{
    // Eine einfache Lichtquelle von schräg oben
    vec3 lightDir = normalize(vec3(0.3, 1.0, 0.2));

    // Ambient
    vec3 colAmbient = vec3(0.2, 0.25, 0.3);

    // Diffuse
    float diff = max(dot(n, lightDir), 0.0);
    vec3 colDiffuse = vec3(0.8, 0.8, 0.7) * diff;

    // Simples Schatten-Raymarching (optional, hier sehr vereinfacht)
    // => Man testet, ob man die Szene in Richtung Licht durchschreitet
    //    Wenn man etwas trifft, dunkler. Hier lassen wir es weg.

    // Spiegelndes Licht (Specular) => hier ein simpler Phong-Ansatz
    vec3 r = reflect(-lightDir, n);
    float spec = pow(max(dot(r, -rd), 0.0), 16.0);
    vec3 colSpec = vec3(1.0) * spec;

    return colAmbient + colDiffuse + colSpec * 0.5;
}

// ----------------------
// Volumetrischer Nebel
// ----------------------
// Einfache Exponential-Fog-Gleichung:
// color = mix( color, fogColor, 1 - exp(-fogDensity * distance) )
vec3 applyFog(vec3 rgb, float dist, float fogDensity)
{
    // Fog-Farbe => heller, leicht bläulicher Ton
    vec3 fogColor = vec3(0.7, 0.8, 0.9);
    float fogAmount = 1.0 - exp(-dist * fogDensity);
    return mix(rgb, fogColor, fogAmount);
}


// ----------------------
// Hauptfunktion
// ----------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalisierte Bildschirmkoordinaten
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Kamera-Setup
    // ro => eye position
    // rd => view direction
    // Wir schauen in -Z Richtung, Y nach oben
    vec3 ro = vec3(0.0, 2.0, 8.0); // Kamera etwas erhöht auf Y=2
    float angle = 0.2 * iTime;     // Kamera dreht sich etwas um Y-Achse
    // Drehe ro und Blickrichtung um Y-Achse
    ro.xz = rotY(angle) * ro.xz;

    // Kamera-Ziel => (0,1,0)
    vec3 target = vec3(0.0, 1.0, 0.0);
    target.xz = rotY(angle) * target.xz;

    vec3 forward = normalize(target - ro);
    vec3 right   = normalize(vec3(forward.z, 0.0, -forward.x));
    vec3 up      = cross(right, forward);

    // Bildschirm-Strahl definieren
    vec3 rd = normalize(uv.x * right + uv.y * up + 1.5 * forward);

    // Raymarch
    vec3 hitPos, hitNormal;
    float t = rayMarch(ro, rd, hitPos, hitNormal);

    // Hintergrundfarbe (falls kein Treffer)
    vec3 col = vec3(0.8, 0.95, 1.0); // Heller Himmel

    if(t > 0.0)
    {
        // Treffer: Beleuchtung berechnen
        vec3 surfCol = lighting(hitPos, hitNormal, rd);

        // Einfache Material-Farbe => hellgrau
        // Du könntest je nach Gebäudehöhe/Position variieren
        vec3 matColor = vec3(0.3, 0.3, 0.32);

        // Endgültige Oberflächenfarbe
        col = matColor * surfCol; 
    }

    // Volumetrischer Nebel hinzufügen
    // => selbst wenn wir kein Objekt getroffen haben, wollen wir Nebel
    float finalDist = (t > 0.0) ? t : 50.0; // falls nix getroffen, großer Dist-Wert
    col = applyFog(col, finalDist, 0.05);  // Nebeldichte anpassen

    fragColor = vec4(col, 1.0);
}
